  1	/**
  2	 * Session API Routes
  3	 *
  4	 * REST endpoints for session data:
  5	 * - GET /api/sessions - list sessions with summaries
  6	 * - GET /api/sessions/:id - get session metadata and detail
  7	 * - GET /api/sessions/:id/events - get session events from events.jsonl
  8	 *
  9	 * AC Coverage:
 10	 * - @ui-session-stream ac-1: Session events as structured blocks
 11	 * - @ui-session-stream ac-4: Session metadata, spec context, budget for context panel
 12	 */
 13	
 14	import { Elysia, t } from 'elysia';
 15	import {
 16	  getSession,
 17	  listSessions,
 18	  readEvents,
 19	  deduplicatePhasedToolCalls,
 20	  getSessionLogSummary,
 21	  getAllSessionLogSummaries,
 22	  resolveSessionId,
 23	  getBudget,
 24	} from '../../sessions/store.js';
 25	import {
 26	  initContext,
 27	  loadAllTasks,
 28	  loadAllItems,
 29	  ReferenceIndex,
 30	} from '../../parser/index.js';
 31	
 32	export function createSessionRoutes() {
 33	  return new Elysia({ prefix: '/api/sessions' })
 34	
 35	    // List all sessions with summaries
 36	    .get('/', async ({ projectContext }) => {
 37	      const ctx = await initContext(projectContext.path);
 38	      const summaries = await getAllSessionLogSummaries(ctx.specDir);
 39	
 40	      // Sort by started_at descending (most recent first)
 41	      summaries.sort((a, b) =>
 42	        new Date(b.started_at).getTime() - new Date(a.started_at).getTime()
 43	      );
 44	
 45	      return {
 46	        items: summaries,
 47	        total: summaries.length,
 48	      };
 49	    })
 50	
 51	    // Get single session metadata
 52	    // AC: @ui-session-stream ac-4 — Includes spec context, budget, and task info
 53	    .get('/:id', async ({ params, projectContext }) => {
 54	      const ctx = await initContext(projectContext.path);
 55	
 56	      // Resolve session ID (supports prefix matching)
 57	      const resolution = await resolveSessionId(ctx.specDir, params.id);
 58	      if (!resolution.ok) {
 59	        if (resolution.error === 'ambiguous') {
 60	          throw new Error(`Ambiguous session ID: ${params.id} matches ${resolution.matches.length} sessions`);
 61	        }
 62	        throw new Error(`Session not found: ${params.id}`);
 63	      }
 64	
 65	      const detail = await getSessionLogSummary(ctx.specDir, resolution.id);
 66	      if (!detail) {
 67	        throw new Error(`Session not found: ${params.id}`);
 68	      }
 69	
 70	      const metadata = await getSession(ctx.specDir, resolution.id);
 71	
 72	      // AC: @ui-session-stream ac-4 — Resolve spec context from task's spec_ref
 73	      let spec_context: {
 74	        spec_ref: string;
 75	        title: string;
 76	        acceptance_criteria: Array<{ id: string; description: string }>;
 77	      } | null = null;
 78	
 79	      if (metadata?.task_id) {
 80	        try {
 81	          const tasks = await loadAllTasks(ctx);
 82	          const items = await loadAllItems(ctx);
 83	          const index = new ReferenceIndex(tasks, items);
 84	          const taskResult = index.resolve(metadata.task_id);
 85	          if (taskResult.ok) {
 86	            const task = taskResult.item as { spec_ref?: string };
 87	            if (task.spec_ref) {
 88	              const specResult = index.resolve(task.spec_ref);
 89	              if (specResult.ok) {
 90	                const specItem = specResult.item as {
 91	                  title: string;
 92	                  acceptance_criteria?: Array<{ description?: string; given?: string }>;
 93	                };
 94	                spec_context = {
 95	                  spec_ref: task.spec_ref,
 96	                  title: specItem.title,
 97	                  acceptance_criteria: (specItem.acceptance_criteria ?? []).map((ac, i) => ({
 98	                    id: `ac-${i + 1}`,
 99	                    description: ac.description ?? ac.given ?? '',
100	                  })),
101	                };
102	              }
103	            }
104	          }
105	        } catch {
106	          // Non-critical — spec context is optional
107	        }
108	      }
109	
110	      // AC: @ui-session-stream ac-4 — Include budget info
111	      let budget: { max_per_cycle: number; started_this_cycle: number } | null = null;
112	      try {
113	        budget = await getBudget(ctx.specDir, resolution.id);
114	      } catch {
115	        // No budget configured — that's fine
116	      }
117	
118	      return {
119	        ...detail,
120	        task_id: metadata?.task_id,
121	        agent_id: metadata?.agent_id,
122	        trigger: metadata?.trigger ?? 'legacy',
123	        spec_context,
124	        budget,
125	      };
126	    })
127	
128	    // Get session events
129	    .get('/:id/events', async ({ params, query, projectContext }) => {
130	      const ctx = await initContext(projectContext.path);
131	
132	      const resolution = await resolveSessionId(ctx.specDir, params.id);
133	      if (!resolution.ok) {
134	        if (resolution.error === 'ambiguous') {
135	          throw new Error(`Ambiguous session ID: ${params.id} matches ${resolution.matches.length} sessions`);
136	        }
137	        throw new Error(`Session not found: ${params.id}`);
138	      }
139	
140	      let events = await readEvents(ctx.specDir, resolution.id);
141	
142	      // Deduplicate phased tool calls
143	      events = deduplicatePhasedToolCalls(events);
144	
145	      // Filter by since_seq if provided (for incremental loading)
146	      const sinceSeq = query.since_seq !== undefined ? parseInt(query.since_seq, 10) : undefined;
147	      if (sinceSeq !== undefined && !isNaN(sinceSeq)) {
148	        events = events.filter(e => e.seq > sinceSeq);
149	      }
150	
151	      return {
152	        events,
153	        total: events.length,
154	      };
155	    }, {
156	      query: t.Object({
157	        since_seq: t.Optional(t.String()),
158	      }),
159	    });
160	}

