245						detail: typeof data.message === 'string' ? data.message : JSON.stringify(data),
246						timestamp: event.ts,
247						seq: event.seq,
248					});
249					break;
250				}
251	
252				case 'agent.dispatched':
253				case 'agent.started':
254				case 'agent.completed':
255				case 'agent.failed':
256				case 'agent.timeout': {
257					const labelMap: Record<string, string> = {
258						'agent.dispatched': 'Agent dispatched',
259						'agent.started': 'Agent started',
260						'agent.completed': 'Agent completed',
261						'agent.failed': 'Agent failed',
262						'agent.timeout': 'Agent timed out',
263					};
264					blocks.push({
265						type: 'system',
266						label: labelMap[event.type] ?? event.type,
267						detail: data.task_ref ? `Task: ${data.task_ref}` : undefined,
268						timestamp: event.ts,
269						seq: event.seq,
270					});
271					break;
272				}
273	
274				case 'prompt.sent': {
275					const phase = data.phase as string | undefined;
276					const iteration = data.iteration as number | undefined;
277					if (phase) {
278						blocks.push({
279							type: 'system',
280							label: `Iteration ${iteration ?? '?'}`,
281							detail: `Phase: ${phase}`,
282							timestamp: event.ts,
283							seq: event.seq,
284						});
285					}
286					break;
287				}
288	
289				case 'iteration.timeout': {
290					blocks.push({
291						type: 'system',
292						label: 'Iteration timeout',
293						timestamp: event.ts,
294						seq: event.seq,
295					});
296					break;
297				}
298			}
299		}
300	
301		return blocks;
302	}
303	
304	/**
305	 * Format a duration in milliseconds to a human-readable string.
306	 */
307	export function formatDuration(ms: number): string {
308		if (ms < 1000) return `${ms}ms`;
309		const secs = Math.floor(ms / 1000);
310		const mins = Math.floor(secs / 60);
311		const hours = Math.floor(mins / 60);
312		if (hours > 0) return `${hours}h ${mins % 60}m`;
313		if (mins > 0) return `${mins}m ${secs % 60}s`;
314		return `${secs}s`;
315	}
316	
317	/**
318	 * Format a timestamp to a time string.
319	 */
320	export function formatTime(ts: number): string {
321		const d = new Date(ts);
322		return d.toLocaleTimeString('en-US', { hour12: false, hour: '2-digit', minute: '2-digit', second: '2-digit' });
323	}
324	
325	/**
326	 * Format elapsed milliseconds to human-readable string (e.g. "2h 5m", "30s").
327	 */
328	export function formatElapsed(ms: number): string {
329		const secs = Math.floor(ms / 1000);
330		const mins = Math.floor(secs / 60);
331		const hours = Math.floor(mins / 60);
332	
333		if (hours > 0) return `${hours}h ${mins % 60}m`;
334		if (mins > 0) return `${mins}m ${secs % 60}s`;
335		return `${secs}s`;
336	}
337	
338	/**
339	 * Format a relative age string from a date (e.g. "5m", "2h", "3d").
340	 */
341	export function formatAge(dateStr: string): string {
342		const now = Date.now();
343		const then = new Date(dateStr).getTime();
344		const diffMs = now - then;
345		const diffMins = Math.floor(diffMs / 60000);
346		const diffHours = Math.floor(diffMins / 60);
347		const diffDays = Math.floor(diffHours / 24);
348	
349		if (diffMins < 1) return 'just now';
350		if (diffMins < 60) return `${diffMins}m`;
351		if (diffHours < 24) return `${diffHours}h`;
352		if (diffDays < 30) return `${diffDays}d`;
353		return `${Math.floor(diffDays / 30)}mo`;
354	}
355	
356	/**
357	 * Extract unique file paths that were changed during a session.
358	 * Looks at Write, Edit, and NotebookEdit tool calls.
359	 *
360	 * AC: @ui-session-stream ac-4 — Files changed during session.
361	 */
362	const WRITE_TOOLS = new Set(['Write', 'Edit', 'NotebookEdit']);
363	
364	export function extractFilesChanged(blocks: DisplayBlock[]): string[] {
365		const files = new Set<string>();
366		for (const block of blocks) {
367			if (block.type !== 'tool_call') continue;
368			if (!WRITE_TOOLS.has(block.toolName)) continue;
369			const input = block.input as Record<string, unknown> | null;
370			if (!input) continue;
371			const filePath = (input.file_path ?? input.notebook_path) as string | undefined;
372			if (filePath) files.add(filePath);
373		}
374		return [...files].sort();
375	}

