  1	<!--
  2	  Session history list view. Links to /sessions/:id for detail.
  3	-->
  4	<script lang="ts">
  5		import { onMount } from 'svelte';
  6		import { base } from '$app/paths';
  7		import type { SessionSummary } from '$lib/api';
  8		import { fetchSessions } from '$lib/api';
  9		import { isStaticMode } from '$lib/stores/mode.svelte';
 10		import { formatElapsed, formatAge } from '$lib/components/session/session-utils';
 11		import { Badge } from '$lib/components/ui/badge';
 12		import Activity from '@lucide/svelte/icons/activity';
 13	
 14		let sessions = $state<SessionSummary[]>([]);
 15		let loading = $state(true);
 16		let error = $state('');
 17	
 18		async function loadSessions() {
 19			loading = true;
 20			error = '';
 21			try {
 22				const data = await fetchSessions();
 23				sessions = data.items;
 24			} catch (err) {
 25				error = err instanceof Error ? err.message : 'Failed to load sessions';
 26			} finally {
 27				loading = false;
 28			}
 29		}
 30	
 31		function statusColor(status: string): string {
 32			switch (status) {
 33				case 'active':
 34					return 'bg-status-in-progress text-status-in-progress-fg';
 35				case 'completed':
 36					return 'bg-status-completed text-status-completed-fg';
 37				case 'failed':
 38					return 'bg-status-blocked text-status-blocked-fg';
 39				default:
 40					return 'bg-status-cancelled text-status-cancelled-fg';
 41			}
 42		}
 43	
 44		onMount(() => {
 45			loadSessions();
 46		});
 47	</script>
 48	
 49	<div class="flex flex-col gap-4 p-6">
 50		<div>
 51			<h1 class="text-2xl font-bold">Sessions</h1>
 52			{#if !loading && sessions.length > 0}
 53				<p class="text-sm text-muted-foreground">{sessions.length} sessions</p>
 54			{/if}
 55		</div>
 56	
 57		{#if error}
 58			<div class="bg-destructive/10 text-destructive p-4 rounded-lg" role="alert">
 59				{error}
 60			</div>
 61		{/if}
 62	
 63		{#if loading}
 64			<div class="space-y-2">
 65				{#each Array(5) as _}
 66					<div class="h-16 rounded-lg bg-muted ds-shimmer"></div>
 67				{/each}
 68			</div>
 69		{:else if sessions.length === 0}
 70			<div class="flex flex-col items-center justify-center py-16" data-testid="sessions-empty">
 71				<Activity class="size-12 text-muted-foreground/30 mb-4" />
 72				<h2 class="text-lg font-medium text-muted-foreground mb-1">No sessions yet</h2>
 73				<p class="text-sm text-muted-foreground">
 74					{#if isStaticMode()}
 75						Session data is not available in static mode.
 76					{:else}
 77						Sessions are created when agents run tasks.
 78					{/if}
 79				</p>
 80			</div>
 81		{:else}
 82			<div class="space-y-2">
 83				{#each sessions as s (s.id)}
 84					<a
 85						href="{base}/sessions/{s.id}"
 86						class="flex items-center gap-4 p-3 rounded-lg border hover:bg-accent/30 transition-colors"
